import { createField, type Field as FieldController } from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createContext, merge, omit, useContext } from "solid-js";

import { Input } from "./input.tsx";
import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

/** What a control's `render` sees: the field's state, so a custom control can paint itself. */
export interface FieldState {
  readonly invalid: () => boolean;
}

export interface FieldProps {
  /** The base of every id the field makes (`<id>-control`, `-label`, `-hint`, `-error`). */
  readonly id?: string;
  readonly required?: boolean;
  /** `true` marks the control invalid, a string is the error message; left out, the field is invalid exactly when `error` is set. */
  readonly invalid?: boolean | string;
  readonly hint?: string;
  readonly error?: string;
  /** Ids the host owns, appended to `aria-describedby` after the field's own. */
  readonly describedby?: string | readonly string[];
  readonly class?: string;
  readonly children?: JSX.Element;
}

export type FieldLabelPartProps = PartProps;

export interface FieldLabelProps extends Renderable<FieldLabelPartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

/** What a control's `render` gets: the props the field owns, and the caller's own. Generic element attributes, since a
 * control is an `Input`, a `Button` or a widget of the host's. */
export type FieldControlPartProps = PartProps;

export interface FieldControlProps
  extends
    Omit<JSX.HTMLAttributes<HTMLElement>, "class" | "ref">,
    Renderable<FieldControlPartProps, FieldState> {
  readonly class?: string;
}

export type FieldMessagePartProps = PartProps;

export interface FieldMessageProps extends Renderable<FieldMessagePartProps, void> {
  readonly class?: string;
}

const FieldContext = createContext<{ readonly field: FieldController }>();

const fieldClass = css.cn(css.display("flex"), css.flexDirection("column"), css.gap(t.space._1));
const labelClass = css.cn(
  css.fontSize(t.font.sizeSm),
  css.fontWeight("500"),
  css.color(t.color.text),
);
const hintClass = css.cn(css.fontSize(t.font.sizeSm), css.color(t.color.muted));
const errorClass = css.cn(css.fontSize(t.font.sizeSm), css.color(t.color.invalid));

/**
 * A form field: `createField` owns the ids, `aria-describedby` and `aria-invalid`, and the parts read them from the context —
 * `Field.Message` goes anywhere inside, and `Field.Control` renders the `Input` or whatever `render` gives it. The control
 * part owns `id` and the ARIA attributes; the caller owns everything else.
 */
export const Field = (props: FieldProps): JSX.Element => {
  const field = createField({
    get id() {
      return props.id;
    },
    get required() {
      return props.required;
    },
    get invalid() {
      return props.invalid;
    },
    get hint() {
      return props.hint;
    },
    get error() {
      return props.error;
    },
    get describedby() {
      return props.describedby;
    },
  });
  return (
    <FieldContext value={{ field }}>
      <div data-part="field" class={css.cn(fieldClass, props.class)}>
        {props.children}
      </div>
    </FieldContext>
  );
};

/** The label: the field's `for` and id, so the control gets its name without one. */
export const FieldLabel = (props: FieldLabelProps): JSX.Element => {
  const { field } = useContext(FieldContext);
  const rest = omit(props, "render", "class", "children");
  const merged = merge(rest, field.labelProps, () => ({
    "data-part": "label",
    class: css.cn(labelClass, props.class),
  }));
  return renderPart(props, merged, undefined, (part) => <label {...part}>{props.children}</label>);
};

/** The control: `id`, `aria-describedby`, `aria-invalid` and `required` from the field, an `Input` by default. */
export const FieldControl = (props: FieldControlProps): JSX.Element => {
  const { field } = useContext(FieldContext);
  const rest = omit(props, "render", "class");
  // the field owns the ids and the ARIA state, the caller the rest: a caller's `aria-invalid` cannot contradict the field
  const merged = merge(rest, field.controlProps, () => ({ class: props.class }));
  return renderPart(props, merged, { invalid: field.invalid }, (part) => <Input {...part} />);
};

/** The hint and the error, always rendered and hidden when absent, so `aria-describedby` never names a missing id. */
export const FieldMessage = (props: FieldMessageProps): JSX.Element => {
  const { field } = useContext(FieldContext);
  return renderPart(
    props,
    { "data-part": "message", class: css.cn(hintClass, props.class) },
    undefined,
    () => (
      <>
        <p {...field.hintProps} data-part="hint" class={hintClass}>
          {field.hint()}
        </p>
        <p {...field.errorProps} data-part="error" class={errorClass}>
          {field.error()}
        </p>
      </>
    ),
  );
};

import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { merge, omit } from "solid-js";

import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

/** What `render` gets: the props of the input, `data-part` and the caller's class merged in. */
export type InputPartProps = PartProps;

export interface InputProps
  extends
    Omit<JSX.InputHTMLAttributes<HTMLInputElement>, "class">,
    Renderable<InputPartProps, void> {
  readonly class?: string;
}

// A text field: one border, one radius, the focus ring a control wears, and the invalid state the field announces with
// aria-invalid rather than a class of its own.
const input = css.cn(
  css.boxSizing("border-box"),
  css.display("block"),
  css.width("100%"),
  css.padding(t.space._2, t.space._3),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.md),
  css.bg(t.color.surface),
  css.color(t.color.fieldText),
  css.fontSize(t.font.size),
  css.hover(css.border("1px solid", t.color.borderHover)),
  css.focusVisible(
    css.outline("2px solid", t.color.focusRing),
    css.outlineOffset("2px"),
    css.border("1px solid", t.color.focusRing),
  ),
  css.attr("aria-invalid", "true")(
    css.border("1px solid", t.color.invalid),
    css.outline("2px solid", t.color.invalid),
  ),
  // A control is disabled either natively (`<Input disabled>`) or by the ARIA a widget announces; the skin's look reads
  // both, since nothing but the caller sets `aria-disabled` on a plain input.
  css.disabled(
    css.bg(t.color.page),
    css.color(t.color.textDisabled),
    css.border("1px solid", t.color.borderDisabled),
    css.cursor("not-allowed"),
  ),
  css.attr("aria-disabled", "true")(
    css.bg(t.color.page),
    css.color(t.color.textDisabled),
    css.border("1px solid", t.color.borderDisabled),
    css.cursor("not-allowed"),
  ),
);

/** An input on the neutral theme: a part of `Field` by default, and a component on its own. */
export const Input = (props: InputProps): JSX.Element => {
  const rest = omit(props, "render", "class");
  const merged = merge(rest, () => ({ "data-part": "input", class: css.cn(input, props.class) }));
  return renderPart(props, merged, undefined, (part) => <input {...part} />);
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import type { JSX } from "@solidjs/web";
import { createSignal, flush } from "solid-js";
import { render } from "@solidjs/web";
import { afterEach, describe, expect, it } from "vite-plus/test";
import { userEvent } from "vite-plus/test/browser";

import { Field, FieldControl, FieldLabel, FieldMessage } from "./field.tsx";
import { Input } from "./input.tsx";

// @cssints/headless checks `createField` against its own contract. This file is the skin's oracle: the starter composes
// the primitive with `Input`, and what a reader meets — the label, the hint and the error, the invalid paint, the disabled
// look, and `render` replacing the control — is only observable through the DOM.

const live: Array<() => void> = [];

const mount = (view: () => JSX.Element): HTMLElement => {
  const root = document.createElement("div");
  document.body.append(root);
  const dispose = render(view, root);
  live.push(() => {
    dispose();
    root.remove();
  });
  flush();
  return root;
};

afterEach(() => {
  for (const dispose of live.splice(0)) {
    dispose();
  }
});

const style = (element: Element): CSSStyleDeclaration => getComputedStyle(element);
const token = (property: "backgroundColor" | "borderTopColor" | "color", name: string): string => {
  const probe = document.createElement("div");
  probe.style[property] = `var(${name})`;
  document.body.append(probe);
  const value = style(probe)[property];
  probe.remove();
  return value;
};

const part = <T extends Element>(root: ParentNode, name: string): T => {
  const element = root.querySelector<T>(`[data-part="${name}"]`);
  if (element === null) {
    throw new Error(`field: no [data-part="${name}"]`);
  }
  return element;
};

describe("Field (the kit's DOM)", () => {
  it("names the control and describes it with the hint and the error", async () => {
    const root = mount(() => (
      <Field id="email" hint="We never share it" error="Enter an address">
        <FieldLabel>Email</FieldLabel>
        <FieldControl render={(props) => <Input {...props} type="email" />} />
        <FieldMessage />
      </Field>
    ));

    expect(part(root, "field").tagName).toBe("DIV");
    const input = part<HTMLInputElement>(root, "input");
    const label = part<HTMLLabelElement>(root, "label");
    // the label is the control's name, through the id the primitive makes
    expect(input.id).toBe("email-control");
    expect(label.getAttribute("for")).toBe("email-control");
    expect(label.textContent).toBe("Email");

    // the hint and the error are the ids the control is described by, in that order
    const described = (input.getAttribute("aria-describedby") ?? "").split(" ");
    expect(described).toEqual(["email-hint", "email-error"]);
    const [hint, error] = described.map((id) => root.querySelector<HTMLElement>(`#${id}`)!);
    expect(hint?.getAttribute("data-part")).toBe("hint");
    expect(hint?.textContent).toBe("We never share it");
    expect(error?.getAttribute("data-part")).toBe("error");
    expect(error?.textContent).toBe("Enter an address");
    // a shown error is an alert; the hint never is
    expect(error?.getAttribute("role")).toBe("alert");
    expect(hint?.hasAttribute("role")).toBe(false);
    expect(hint?.checkVisibility()).toBe(true);
    expect(error?.checkVisibility()).toBe(true);

    // a control with a label of its own: a click on the label puts the focus in the input
    await userEvent.click(label);
    expect(document.activeElement).toBe(input);
  });

  it("follows the error with aria-invalid and the described-by list", () => {
    const [error, setError] = createSignal<string>();
    const root = mount(() => (
      <Field id="name" hint="As it appears on the card" error={error()}>
        <FieldLabel>Name</FieldLabel>
        <FieldControl />
        <FieldMessage />
      </Field>
    ));
    const input = part<HTMLInputElement>(root, "input");
    const resting = style(input).borderTopColor;

    // a plain field references nothing it does not show, and is not invalid
    expect(input.getAttribute("aria-describedby")).toBe("name-hint");
    expect(input.hasAttribute("aria-invalid")).toBe(false);
    expect(part(root, "error").checkVisibility()).toBe(false);
    expect(style(input).borderTopColor).toBe(resting);

    setError("Too short");
    flush();

    // the hint stays; the error joins it and marks the control invalid, which the skin paints
    expect(input.getAttribute("aria-describedby")).toBe("name-hint name-error");
    expect(input.getAttribute("aria-invalid")).toBe("true");
    expect(part(root, "error").textContent).toBe("Too short");
    expect(part(root, "error").checkVisibility()).toBe(true);
    expect(style(input).borderTopColor).toBe(token("borderTopColor", "--color-invalid"));

    setError(undefined);
    flush();

    // the state the field announces is the only copy: clearing it clears the paint
    expect(input.getAttribute("aria-describedby")).toBe("name-hint");
    expect(input.hasAttribute("aria-invalid")).toBe(false);
    expect(part(root, "error").checkVisibility()).toBe(false);
    expect(style(input).borderTopColor).toBe(resting);
  });

  it("keeps a disabled control's look and drops it out of the tab order", async () => {
    const root = mount(() => (
      <>
        <button data-part="before">Before</button>
        <Field id="locked">
          <FieldLabel>Locked</FieldLabel>
          <FieldControl render={(props) => <Input {...props} disabled />} />
        </Field>
        <button data-part="after">After</button>
      </>
    ));
    const input = part<HTMLInputElement>(root, "input");
    const before = part<HTMLElement>(root, "before");
    const after = part<HTMLElement>(root, "after");

    expect(input.disabled).toBe(true);
    // the disabled look is the skin's: the theme's page and disabled border, not the resting surface
    expect(style(input).backgroundColor).toBe(token("backgroundColor", "--color-page"));
    expect(style(input).borderTopColor).toBe(token("borderTopColor", "--color-border-disabled"));
    expect(style(input).cursor).toBe("not-allowed");

    // and it is not a tab stop: the focus goes from what precedes it to what follows it
    before.focus();
    expect(document.activeElement).toBe(before);
    await userEvent.tab();
    expect(document.activeElement).toBe(after);
    input.focus();
    expect(document.activeElement).not.toBe(input);
  });

  it("lets render replace the control and keeps the state live", () => {
    const [error, setError] = createSignal<string>();
    const root = mount(() => (
      <Field id="notes" error={error()}>
        <FieldLabel>Notes</FieldLabel>
        <FieldControl
          render={(props, state) => (
            <textarea
              {...props}
              data-part="control"
              data-live={state.invalid() ? "invalid" : "valid"}
            />
          )}
        />
        <FieldMessage />
      </Field>
    ));
    const control = part<HTMLTextAreaElement>(root, "control");

    // the field hands its ids and ARIA to whatever element the caller renders
    expect(control.tagName).toBe("TEXTAREA");
    expect(control.id).toBe("notes-control");
    expect(control.dataset["live"]).toBe("valid");
    expect(control.hasAttribute("aria-invalid")).toBe(false);

    setError("Too short");
    flush();

    // the state the kit reads is an accessor, so a replaced part follows without a re-render
    expect(control.dataset["live"]).toBe("invalid");
    expect(control.getAttribute("aria-invalid")).toBe("true");
    expect(control.getAttribute("aria-describedby")).toBe("notes-error");
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
